  "open-close-css": {
    title: "Open / close CSS",
    code: ".lightbox-demo-backdrop {\n  opacity: 0;\n  /* Open/close uses --duration-open easeOutExpo (the fallbacks). During a\n     pull-to-dismiss snap-back the library publishes --lightbox-pull-snap-\n     duration/-easing, so the fade springs back in lockstep with the item —\n     tweak the snap-back once and both stay matched. */\n  transition: opacity var(--lightbox-pull-snap-duration, var(--duration-open))\n    var(--lightbox-pull-snap-easing, var(--ease-out-expo));\n}\n\n/* First frame when `data-open` appears — then pull-progress.css owns open opacity. */\n@starting-style {\n  .lightbox-demo-backdrop[data-open] {\n    opacity: 0;\n  }\n}\n\n.lightbox-demo-content {\n  opacity: 0;\n  /* Shares --duration-open with the backdrop + morph so the surface, scrim and\n     image resolve together instead of the content settling ~60ms early. */\n  transition: opacity var(--duration-open) var(--ease-out-expo);\n}\n\n.lightbox-demo-content[data-open] {\n  opacity: 1;\n}\n\n@starting-style {\n  .lightbox-demo-content[data-open] {\n    opacity: 0;\n  }\n}\n",
    source: "app/lightbox-demo/open-close.css",
  },
  "pull-progress-css": {
    title: "Pull progress CSS",
    code: ".lightbox-demo-backdrop[data-open] {\n  /* --lightbox-pull-progress: 0 → 1 while dragging */\n  opacity: calc(1 - var(--lightbox-pull-progress, 0) * 0.6);\n}\n\n.lightbox-demo-backdrop[data-pulling] {\n  transition: none; /* follow the finger */\n}\n\n/*\n * Snug gallery slides — inactive cards ease with zoom + pull progress.\n * `--lightbox-pull-progress` inherits from Content. While `data-pulling`,\n * transition is off so opacity tracks the finger; on release the library\n * publishes snap duration/easing so the fade springs back with the item.\n */\n.lightbox-demo-slide-snug {\n  transition: opacity var(--lightbox-pull-snap-duration, 500ms)\n    var(--lightbox-pull-snap-easing, var(--ease-out-expo));\n}\n\n.lightbox-demo-content[data-pulling] .lightbox-demo-slide-snug {\n  transition: none;\n}\n\n/* Active card stays solid (pull transform is the dismiss cue). */\n.lightbox-demo-slide-snug:has([data-active]) {\n  opacity: 1;\n}\n\n/* Inactive: dim hard with pull; when zoomed, rest at 0.6 then nearly vanish. */\n.lightbox-demo-content:not([data-zoomed]) .lightbox-demo-slide-snug:not(:has([data-active])) {\n  opacity: calc(1 - var(--lightbox-pull-progress, 0) * 0.85);\n}\n\n.lightbox-demo-content[data-zoomed] .lightbox-demo-slide-snug:not(:has([data-active])) {\n  opacity: calc(0.6 * (1 - var(--lightbox-pull-progress, 0) * 0.85));\n  pointer-events: none;\n}\n\n.lightbox-demo-content[data-zoomed] .lightbox-demo-slide-snug:has([data-active]) {\n  z-index: 20;\n}\n\n/* Light scrim used by LightboxGallery (responsive-gallery chrome). */\n.lightbox-demo-backdrop-light {\n  background-color: rgb(255 255 255 / 0.9);\n}\n\nhtml.dark .lightbox-demo-backdrop-light {\n  background-color: rgb(0 0 0 / 0.9);\n}\n",
    source: "app/lightbox-demo/pull-progress.css",
  },
